-- ============================================================
-- ③ المقال 1: إجراءات نقل الجثمان دولياً خطوة بخطوة
-- ============================================================

INSERT INTO blogs (id, name, description, image, meta_title, meta_description, meta_keywords, code, category_id, alt_txt, created_at, updated_at) VALUES (
1,
'{"ar":"إجراءات نقل الجثمان دولياً خطوة بخطوة","en":"Step-by-Step Guide to International Deceased Repatriation","ru":"Пошаговое руководство по международной репатриации","fr":"Guide étape par étape pour le rapatriement international","es":"Guía paso a paso para la repatriación internacional de fallecidos"}',
'{"ar":"تعرف على الخطوات الكاملة لنقل جثمان المتوفى من مصر إلى أي دولة في العالم، من استخراج شهادة الوفاة وحتى وصول الجثمان إلى ذويه.","en":"Learn the complete steps for repatriating a deceased person from Egypt to any country in the world, from obtaining the death certificate to the final delivery to the family.","ru":"Узнайте полный порядок репатриации усопшего из Египта в любую страну мира — от получения свидетельства о смерти до передачи семье.","fr":"Découvrez toutes les étapes du rapatriement d\'un défunt depuis l\'Égypte vers n\'importe quel pays du monde.","es":"Conozca todos los pasos para repatriar a un fallecido desde Egipto hacia cualquier país del mundo."}',
NULL,
'{"ar":"إجراءات نقل الجثمان دولياً | دليل شامل - رضوان","en":"International Deceased Repatriation Procedures | Complete Guide - Radwan","ru":"Процедуры международной репатриации | Полное руководство - Радван","fr":"Procédures de rapatriement international | Guide complet - Radwan","es":"Procedimientos de repatriación internacional | Guía completa - Radwan"}',
'{"ar":"دليل شامل لإجراءات نقل الجثمان دولياً من مصر. تعرف على المستندات المطلوبة والجهات المعنية والخطوات القانونية مع شركة رضوان.","en":"A complete guide to international deceased repatriation from Egypt. Learn about required documents, involved authorities, and legal steps with Radwan.","ru":"Полное руководство по международной репатриации из Египта. Документы, ведомства и юридические шаги с компанией Радван.","fr":"Guide complet pour le rapatriement depuis l\'Égypte. Documents requis, autorités concernées et démarches légales avec Radwan.","es":"Guía completa para la repatriación desde Egipto. Documentos requeridos, autoridades involucradas y pasos legales con Radwan."}',
'{"ar":"نقل الجثمان دولياً, إجراءات شحن الجثامين, تصاريح النقل الدولي, رضوان لنقل الموتى","en":"international repatriation, body repatriation Egypt, deceased transport procedures, Radwan funeral services","ru":"международная репатриация, перевозка усопших, репатриация из Египта, Радван","fr":"rapatriement international, transport de défunt Égypte, procédures funéraires, Radwan","es":"repatriación internacional, traslado de fallecidos Egipto, procedimientos funerarios, Radwan"}',
'RPT-001',1,
'{"ar":"إجراءات نقل الجثمان دولياً","en":"International Deceased Repatriation Procedures","ru":"Процедуры международной репатриации","fr":"Procédures de rapatriement international","es":"Procedimientos de repatriación internacional"}',
NOW(),NOW());

INSERT INTO blog_details (blog_id, title, content, sort_order, created_at, updated_at) VALUES
(1,
'{"ar":"الخطوة الأولى: الإبلاغ الفوري والتوثيق","en":"Step 1: Immediate Notification & Documentation","ru":"Шаг 1: Немедленное уведомление и документирование","fr":"Étape 1 : Notification immédiate et documentation","es":"Paso 1: Notificación inmediata y documentación"}',
'{"ar":"عند وفاة شخص خارج بلده، يجب التواصل فوراً مع شركة رضوان على الرقم +201500017444. يتولى فريقنا التنسيق مع المستشفى للحصول على شهادة الوفاة الرسمية، وإخطار الجهات الأمنية المختصة، وتحديد هوية المتوفى بشكل رسمي. كل دقيقة تمر لها أهميتها في ضمان سرعة الإجراءات.","en":"When a person passes away outside their home country, immediately contact Radwan at +201500017444. Our team coordinates with the hospital to obtain the official death certificate, notifies the competent security authorities, and formally identifies the deceased. Every minute matters in ensuring swift procedures.","ru":"При смерти человека за рубежом немедленно свяжитесь с компанией Радван по номеру +201500017444. Наша команда координирует получение официального свидетельства о смерти и устанавливает личность усопшего.","fr":"En cas de décès à l\'étranger, contactez immédiatement Radwan au +201500017444. Notre équipe coordonne l\'obtention du certificat de décès officiel et procède à l\'identification formelle du défunt.","es":"Ante un fallecimiento en el extranjero, contacte de inmediato a Radwan al +201500017444. Nuestro equipo coordina la obtención del certificado de defunción oficial y la identificación formal del fallecido."}',
1,NOW(),NOW()),
(1,
'{"ar":"الخطوة الثانية: التنسيق مع السفارة والقنصلية","en":"Step 2: Embassy & Consulate Coordination","ru":"Шаг 2: Координация с посольством и консульством","fr":"Étape 2 : Coordination avec l\'ambassade et le consulat","es":"Paso 2: Coordinación con la embajada y el consulado"}',
'{"ar":"تتولى شركة رضوان التواصل المباشر مع سفارة أو قنصلية دولة المتوفى في القاهرة لاستخراج تصريح السفر الرسمي. تعتمد شركتنا على شراكات دبلوماسية مباشرة مع أكثر من 30 سفارة، مما يضمن سرعة الموافقة وتجنب التأخيرات البيروقراطية. تشمل المستندات المطلوبة: جواز سفر المتوفى، شهادة الوفاة، وموافقة النيابة العامة في الحالات القانونية.","en":"Radwan directly liaises with the deceased\'s home country embassy or consulate in Cairo to obtain the official travel permit. Our company maintains direct diplomatic partnerships with over 30 embassies, ensuring fast approval and avoiding bureaucratic delays. Required documents include: the deceased\'s passport, death certificate, and public prosecution approval in legal cases.","ru":"Радван напрямую взаимодействует с посольством страны усопшего в Каире для получения официального разрешения. Компания поддерживает прямые дипломатические связи с более чем 30 посольствами.","fr":"Radwan assure la liaison directe avec l\'ambassade du pays du défunt au Caire. Notre société maintient des partenariats diplomatiques avec plus de 30 ambassades.","es":"Radwan gestiona directamente el permiso de viaje ante la embajada del país del fallecido en El Cairo, manteniendo alianzas diplomáticas con más de 30 embajadas."}',
2,NOW(),NOW()),
(1,
'{"ar":"الخطوة الثالثة: التجهيز والتغليف المعتمد دولياً","en":"Step 3: Certified International Preparation & Packaging","ru":"Шаг 3: Сертифицированная подготовка и упаковка","fr":"Étape 3 : Préparation et emballage certifiés","es":"Paso 3: Preparación y embalaje certificado internacionalmente"}',
'{"ar":"يُجهَّز الجثمان وفق أعلى المعايير الصحية الدولية المطلوبة للشحن الجوي. يشمل التجهيز: التحنيط الطبي المعتمد، التغليف الحراري، والتابوت المبطن بالزنك المحكم وفق اشتراطات منظمة IATA وشركات الطيران الدولية. نصدر شهادة التحنيط الرسمية اللازمة للجمارك في دولة الوصول.","en":"The deceased is prepared according to the highest international health standards required for air freight. Preparation includes: certified medical embalming, thermal wrapping, and a hermetically sealed zinc-lined casket complying with IATA regulations. We issue the official embalming certificate required by customs at the destination.","ru":"Усопший подготавливается по высочайшим международным стандартам для авиаперевозки: сертифицированное бальзамирование, термоупаковка и герметичный цинковый гроб согласно IATA.","fr":"Le défunt est préparé selon les normes sanitaires internationales pour le fret aérien : embaumement certifié, emballage thermique et cercueil en zinc hermétique conforme IATA.","es":"El fallecido se prepara según los estándares sanitarios internacionales para transporte aéreo: embalsamamiento certificado, embalaje térmico y ataúd de zinc hermético conforme IATA."}',
3,NOW(),NOW()),
(1,
'{"ar":"الخطوة الرابعة: الشحن الجوي والاستلام","en":"Step 4: Air Freight & Final Delivery","ru":"Шаг 4: Авиаперевозка и финальная передача","fr":"Étape 4 : Fret aérien et remise finale","es":"Paso 4: Transporte aéreo y entrega final"}',
'{"ar":"بعد استكمال كافة التصاريح، ينسق فريق رضوان مع شركات الطيران لحجز مكان الشحن في أقرب رحلة متاحة. نتولى تسليم كافة المستندات الأصلية للعائلة في مطار الوصول. تستغرق العملية من البداية للنهاية بين 24 إلى 72 ساعة في الغالب. للتواصل الفوري: +201500017444 أو +201116779707 أو +201009924201.","en":"After completing all permits, the Radwan team coordinates with airlines to book the earliest available cargo flight. We deliver all original documents to the family at the destination airport. The entire process typically takes 24 to 72 hours. For immediate contact: +201500017444 or +201116779707 or +201009924201.","ru":"После оформления разрешений Радван координирует с авиакомпаниями бронирование ближайшего рейса. Все оригиналы документов передаются семье в аэропорту. Весь процесс занимает 24–72 часа. Тел: +201500017444.","fr":"Après tous les permis, Radwan réserve le premier vol cargo disponible. Tous les documents sont remis à la famille à l\'aéroport de destination. Le processus prend 24 à 72 heures. Contact : +201500017444.","es":"Tras obtener todos los permisos, Radwan reserva el vuelo de carga más próximo. Todos los documentos se entregan a la familia en destino. El proceso toma 24–72 horas. Contacto: +201500017444."}',
4,NOW(),NOW());

-- ============================================================
-- المقال 2: المستندات المطلوبة لشحن الجثمان
-- ============================================================

INSERT INTO blogs (id, name, description, image, meta_title, meta_description, meta_keywords, code, category_id, alt_txt, created_at, updated_at) VALUES (
2,
'{"ar":"المستندات المطلوبة لشحن الجثمان دولياً من مصر","en":"Required Documents for International Body Shipping from Egypt","ru":"Документы для международной перевозки усопшего из Египта","fr":"Documents requis pour l\'expédition internationale d\'un corps depuis l\'Égypte","es":"Documentos requeridos para el envío internacional de restos desde Egipto"}',
'{"ar":"قائمة شاملة بجميع الوثائق الرسمية المطلوبة لاستخراج تصاريح شحن الجثمان من مصر إلى الخارج، مع شرح دور كل جهة حكومية في العملية.","en":"A comprehensive list of all official documents required to obtain permits for shipping a body from Egypt abroad, with an explanation of each government authority\'s role in the process.","ru":"Полный список официальных документов для получения разрешений на вывоз усопшего из Египта за рубеж с объяснением роли каждого ведомства.","fr":"Liste complète des documents officiels requis pour l\'expédition d\'un corps depuis l\'Égypte, avec le rôle de chaque autorité.","es":"Lista completa de todos los documentos oficiales requeridos para el envío de restos desde Egipto al extranjero."}',
NULL,
'{"ar":"مستندات شحن الجثمان من مصر | الوثائق الرسمية - رضوان","en":"Documents for Body Shipping from Egypt | Official Papers - Radwan","ru":"Документы для перевозки из Египта | Официальные бумаги - Радван","fr":"Documents pour expédition depuis l\'Égypte | Papiers officiels - Radwan","es":"Documentos para envío desde Egipto | Papeles oficiales - Radwan"}',
'{"ar":"تعرف على جميع المستندات الرسمية المطلوبة لشحن جثمان المتوفى من مصر إلى الخارج والجهات المسؤولة عن إصدارها مع شركة رضوان.","en":"Learn about all official documents required to ship a deceased person from Egypt abroad, and the authorities responsible for issuing them, with Radwan.","ru":"Узнайте обо всех официальных документах для вывоза усопшего из Египта и органах их выдающих с компанией Радван.","fr":"Découvrez tous les documents officiels nécessaires pour expédier un défunt depuis l\'Égypte et les autorités responsables.","es":"Conozca todos los documentos oficiales necesarios para enviar un fallecido desde Egipto y las autoridades encargadas."}',
'{"ar":"وثائق نقل الجثمان, مستندات شحن الموتى, تصريح نقل الجثمان, شهادة الوفاة, رضوان","en":"body shipping documents Egypt, deceased transport papers, repatriation permit, death certificate Egypt, Radwan","ru":"документы для перевозки усопшего, разрешение на вывоз, свидетельство о смерти Египет, Радван","fr":"documents transport défunt Égypte, permis rapatriement, certificat décès, Radwan","es":"documentos traslado fallecido Egipto, permiso repatriación, certificado defunción, Radwan"}',
'DOC-002',4,
'{"ar":"المستندات المطلوبة لشحن الجثمان","en":"Required Documents for Body Shipping","ru":"Документы для перевозки усопшего","fr":"Documents requis pour l\'expédition","es":"Documentos requeridos para el envío"}',
NOW(),NOW());

INSERT INTO blog_details (blog_id, title, content, sort_order, created_at, updated_at) VALUES
(2,
'{"ar":"أولاً: المستندات الأساسية من الجهات المصرية","en":"First: Essential Documents from Egyptian Authorities","ru":"Первое: Основные документы от египетских органов","fr":"Premièrement : Documents essentiels des autorités égyptiennes","es":"Primero: Documentos esenciales de las autoridades egipcias"}',
'{"ar":"تشمل المستندات الأساسية المطلوبة من الجهات المصرية: 1) شهادة الوفاة الطبية الرسمية الصادرة من المستشفى أو الطبيب المعالج. 2) تصريح الدفن أو النقل الصادر من مكتب الصحة المختص. 3) موافقة النيابة العامة في حالات الوفاة غير الطبيعية أو الحوادث. 4) تصريح مشرحة زينهم في حالات التشريح الجنائي. 5) جواز سفر المتوفى الأصلي. تتولى شركة رضوان استخراج جميع هذه المستندات نيابةً عن الأسرة.","en":"Essential documents required from Egyptian authorities: 1) Official medical death certificate from the hospital or treating physician. 2) Burial or transport permit from the competent health office. 3) Public prosecution approval in cases of unnatural death or accidents. 4) Zeinhom Morgue permit in forensic autopsy cases. 5) The deceased\'s original passport. Radwan handles obtaining all these documents on behalf of the family.","ru":"Основные документы от египетских органов: 1) Официальное медицинское свидетельство о смерти. 2) Разрешение от санитарного бюро. 3) Согласие прокуратуры при насильственной смерти. 4) Разрешение морга Зейнхом. 5) Оригинал паспорта. Радван оформляет все документы от имени семьи.","fr":"Documents des autorités égyptiennes : 1) Certificat médical de décès. 2) Permis du bureau de santé. 3) Autorisation du parquet. 4) Permis de la morgue Zeinhom. 5) Passeport original. Radwan obtient tous ces documents au nom de la famille.","es":"Documentos de autoridades egipcias: 1) Certificado médico de defunción. 2) Permiso de la oficina de salud. 3) Autorización de la Fiscalía. 4) Permiso de la morgue Zeinhom. 5) Pasaporte original. Radwan gestiona todos estos documentos en nombre de la familia."}',
1,NOW(),NOW()),
(2,
'{"ar":"ثانياً: المستندات الدبلوماسية من السفارة","en":"Second: Diplomatic Documents from the Embassy","ru":"Второе: Дипломатические документы от посольства","fr":"Deuxièmement : Documents diplomatiques de l\'ambassade","es":"Segundo: Documentos diplomáticos de la embajada"}',
'{"ar":"بعد استكمال المستندات المصرية، تتولى شركة رضوان استخراج المستندات الدبلوماسية من سفارة دولة المتوفى في القاهرة، وتشمل: 1) تصريح السفر القنصلي الخاص بنقل الرفات. 2) موافقة السفارة على مستندات التحنيط. 3) شهادة عدم الممانعة القنصلية. 4) التحقق من هوية المتوفى لدى الجهات القنصلية. تختلف المتطلبات بحسب كل دولة، ولهذا تبرز أهمية التعامل مع متخصصين مثل شركة رضوان التي تمتلك علاقات دبلوماسية راسخة.","en":"After completing the Egyptian documents, Radwan handles obtaining the diplomatic documents from the deceased\'s country embassy in Cairo: 1) Consular travel permit for remains transport. 2) Embassy approval of embalming documents. 3) Consular Non-Objection Certificate. 4) Identity verification by consular authorities. Requirements vary by country, which is why working with specialists like Radwan is essential.","ru":"После египетских документов Радван получает дипломатические документы от посольства: 1) Консульское разрешение. 2) Согласие посольства на бальзамирование. 3) Консульский сертификат об отсутствии возражений. Требования варьируются по странам.","fr":"Après les documents égyptiens, Radwan obtient les documents diplomatiques : 1) Permis consulaire. 2) Accord de l\'ambassade. 3) Certificat de non-objection. Les exigences varient selon les pays.","es":"Tras los documentos egipcios, Radwan obtiene los diplomáticos: 1) Permiso consular. 2) Aprobación de embajada. 3) Certificado de no objeción. Los requisitos varían según el país."}',
2,NOW(),NOW()),
(2,
'{"ar":"ثالثاً: وثائق الشحن الجوي والجمارك","en":"Third: Airline & Customs Documents","ru":"Третье: Документы авиакомпании и таможни","fr":"Troisièmement : Documents de la compagnie aérienne et des douanes","es":"Tercero: Documentos de la aerolínea y aduanas"}',
'{"ar":"المرحلة الأخيرة تتضمن وثائق الشحن الجوي: 1) شهادة التحنيط الطبي المعتمدة. 2) بوليصة الشحن الجوي Air Waybill. 3) تصريح الصحة للشحن من وزارة الصحة. 4) فاتورة المحتويات الرسمية للصندوق. 5) بطاقة التعريف بالهوية داخل التابوت. تتولى شركة رضوان إعداد وتوثيق جميع هذه الوثائق، مما يضمن مرور الشحنة دون أي عراقيل جمركية.","en":"The final stage involves air freight and customs documents: 1) Certified medical Embalming Certificate. 2) Air Waybill for remains. 3) Health shipping permit from the Ministry of Health. 4) Official contents invoice for the casket. 5) Identity tag inside the casket. Radwan fully prepares and authenticates all these documents, ensuring the shipment passes without any customs obstacles.","ru":"Заключительный этап: 1) Свидетельство о бальзамировании. 2) Авианакладная. 3) Санитарное разрешение Минздрава. 4) Инвентарный список. 5) Идентификационная бирка. Радван полностью подготавливает все документы.","fr":"Étape finale : 1) Certificat d\'embaumement. 2) Lettre de transport aérien. 3) Permis sanitaire du Ministère. 4) Facture officielle. 5) Étiquette d\'identification. Radwan prépare intégralement ces documents.","es":"Etapa final: 1) Certificado de embalsamamiento. 2) Carta de porte aéreo. 3) Permiso sanitario del Ministerio. 4) Factura oficial. 5) Etiqueta de identificación. Radwan prepara íntegramente todos estos documentos."}',
3,NOW(),NOW());

-- ============================================================
-- المقال 3: دليل اختيار التابوت للشحن الجوي
-- ============================================================

INSERT INTO blogs (id, name, description, image, meta_title, meta_description, meta_keywords, code, category_id, alt_txt, created_at, updated_at) VALUES (
3,
'{"ar":"دليل اختيار التابوت المناسب للشحن الجوي الدولي","en":"Guide to Choosing the Right Casket for International Air Shipping","ru":"Руководство по выбору гроба для международной авиаперевозки","fr":"Guide pour choisir le bon cercueil pour l\'expédition aérienne internationale","es":"Guía para elegir el ataúd adecuado para el envío aéreo internacional"}',
'{"ar":"تعرف على أنواع التوابيت المعتمدة دولياً للشحن الجوي، والفرق بين تابوت الشحن الجوي وتابوت الدفن المحلي، وكيف تختار الأنسب لظروف عائلتك.","en":"Learn about internationally approved casket types for air shipping, the difference between an air freight casket and a local burial casket, and how to choose the most suitable one for your family.","ru":"Узнайте о международно одобренных типах гробов для авиаперевозки и их отличиях от гробов для местного захоронения.","fr":"Découvrez les types de cercueils approuvés pour le fret aérien et la différence avec les cercueils d\'inhumation locale.","es":"Conozca los tipos de ataúdes aprobados para envío aéreo y la diferencia con los ataúdes de entierro local."}',
NULL,
'{"ar":"دليل اختيار التابوت للشحن الجوي | رضوان للتوابيت","en":"Casket Selection Guide for Air Shipping | Radwan Caskets","ru":"Руководство по выбору гроба для авиаперевозки | Радван","fr":"Guide de sélection de cercueil pour fret aérien | Radwan","es":"Guía de selección de ataúd para envío aéreo | Radwan"}',
'{"ar":"دليل شامل لاختيار التابوت المناسب للشحن الجوي الدولي مع شركة رضوان. تعرف على الفرق بين التوابيت وأنواعها ومواصفاتها.","en":"A comprehensive guide to choosing the right casket for international air shipping with Radwan. Learn about types, specifications, and differences.","ru":"Полное руководство по выбору гроба для международной авиаперевозки с Радван. Типы, характеристики и различия.","fr":"Guide complet pour choisir le bon cercueil pour le fret aérien avec Radwan. Types, caractéristiques et différences.","es":"Guía completa para elegir el ataúd para envío aéreo internacional con Radwan. Tipos, especificaciones y diferencias."}',
'{"ar":"تابوت الشحن الجوي, توابيت للنقل الدولي, تابوت مبطن بالزنك, صندوق الجثمان, رضوان","en":"air freight casket, international shipping casket, zinc lined casket, IATA casket, Radwan","ru":"авиационный гроб, гроб международная перевозка, цинковый гроб IATA, Радван","fr":"cercueil fret aérien, cercueil transport international, cercueil zinc IATA, Radwan","es":"ataúd carga aérea, ataúd transporte internacional, ataúd zinc IATA, Radwan"}',
'CSK-003',3,
'{"ar":"دليل اختيار التابوت للشحن الجوي","en":"Casket Selection Guide for Air Shipping","ru":"Руководство по выбору гроба для авиаперевозки","fr":"Guide de sélection de cercueil pour fret aérien","es":"Guía de selección de ataúd para envío aéreo"}',
NOW(),NOW());

INSERT INTO blog_details (blog_id, title, content, sort_order, created_at, updated_at) VALUES
(3,
'{"ar":"التابوت المبطن بالزنك: المعيار الدولي للشحن الجوي","en":"Zinc-Lined Casket: The International Standard for Air Shipping","ru":"Цинковый гроб: международный стандарт авиаперевозки","fr":"Cercueil doublé de zinc : la norme internationale pour le fret aérien","es":"Ataúd con revestimiento de zinc: el estándar internacional"}',
'{"ar":"التابوت المبطن بالزنك هو المتطلب الأساسي لدى معظم شركات الطيران الدولية لقبول شحنات الرفات البشرية. يُصنع من خشب متين يحتوي بداخله على طبقة من الزنك المحكم الإغلاق يتم لحامها حرارياً لمنع أي تسرب. هذه المواصفات تضمن: الحفاظ على الجثمان خلال رحلات الشحن الطويلة، الامتثال لاشتراطات IATA، وقبول الشحنة في جمارك دولة الوصول. تتوفر لدى رضوان تشكيلة متنوعة من التوابيت المبطنة بالزنك بتصاميم مختلفة.","en":"The zinc-lined casket is the primary requirement of most international airlines for accepting human remains shipments. It is made of solid wood with an inner layer of hermetically sealed zinc thermally welded to prevent any leakage. These specifications ensure: preservation during long freight journeys, IATA compliance, and acceptance at destination customs. Radwan offers a variety of zinc-lined caskets in different designs.","ru":"Цинковый гроб — основное требование большинства международных авиакомпаний. Изготовлен из прочного дерева с герметично запаянным цинковым вкладышем. Обеспечивает сохранность, соответствие IATA и беспрепятственное таможенное оформление. Радван предлагает широкий выбор.","fr":"Le cercueil doublé de zinc est exigé par la plupart des compagnies aériennes. Il garantit la conservation, la conformité IATA et le passage en douane. Radwan propose une gamme variée.","es":"El ataúd con zinc es requerido por la mayoría de aerolíneas. Garantiza conservación, cumplimiento IATA y paso por aduanas. Radwan ofrece amplia variedad."}',
1,NOW(),NOW()),
(3,
'{"ar":"توابيت الدفن المحلي والجرار التذكارية","en":"Local Burial Caskets & Commemorative Urns","ru":"Гробы для местного захоронения и памятные урны","fr":"Cercueils d\'inhumation locale et urnes cinéraires","es":"Ataúdes para entierro local y urnas conmemorativas"}',
'{"ar":"لمن يرغب في الدفن داخل مصر، توفر شركة رضوان مجموعة واسعة من توابيت الدفن المحلي بأحجام وتصاميم متنوعة تناسب مختلف الاحتياجات والميزانيات. تتراوح المواد بين الخشب البسيط والخشب الفاخر المصقول. أما جرار الرماد، فمتوفرة بتصاميم راقية من الرخام الفاخر والخشب المصقول والمعادن المقاومة، محكمة الإغلاق ومعتمدة للسفر الدولي. يساعد فريقنا العائلة في الاختيار المناسب بكل تعاطف واحترافية.","en":"For those wishing to bury in Egypt, Radwan offers a wide range of local burial caskets in various sizes and designs. Materials range from simple wood to polished premium timber. Commemorative ash urns are available in elegant designs of premium marble, polished wood, and stainless metals, all hermetically sealed and approved for international travel. Our team helps families choose with empathy and professionalism.","ru":"Для захоронения в Египте Радван предлагает широкий выбор гробов. Памятные урны из мрамора, дерева и металла — герметичны, одобрены для перевозки. Наша команда помогает с выбором.","fr":"Pour les inhumations en Égypte, Radwan propose divers cercueils. Les urnes cinéraires en marbre, bois et métal sont hermétiques et approuvées pour les voyages. Notre équipe accompagne avec empathie.","es":"Para entierros en Egipto, Radwan ofrece variedad de ataúdes. Urnas de mármol, madera y metal, herméticamente selladas y aprobadas para viajes. Nuestro equipo acompaña a las familias."}',
2,NOW(),NOW());

