INSERT INTO blogs (id, name, description, image, meta_title, meta_description, meta_keywords, code, category_id, alt_txt, created_at, updated_at) VALUES (
4,
'{"ar":"ماذا تفعل فوراً عند وفاة أحد أفراد عائلتك خارج مصر","en":"What to Do Immediately When a Family Member Dies Abroad","ru":"Что делать немедленно при смерти члена семьи за рубежом","fr":"Que faire immédiatement quand un membre de la famille décède à l\'étranger","es":"Qué hacer de inmediato cuando un familiar fallece en el extranjero"}',
'{"ar":"دليل عملي للعائلات في لحظات الصدمة: الخطوات الأولى والأكثر أهمية التي يجب اتخاذها فور تلقي نبأ وفاة أحد الأقارب خارج البلاد، وكيف تتصرف بهدوء وحكمة.","en":"A practical guide for families in moments of shock: the first and most important steps to take upon receiving news of a relative\'s death abroad, and how to act calmly and wisely.","ru":"Практическое руководство для семей в момент потрясения: первые и важнейшие шаги после получения известия о смерти родственника за рубежом.","fr":"Guide pratique pour les familles en état de choc : premières étapes lors d\'un décès à l\'étranger.","es":"Guía práctica para familias en estado de conmoción: primeros pasos ante el fallecimiento de un familiar en el extranjero."}',
NULL,
'{"ar":"ماذا تفعل عند وفاة أحد أقاربك خارج مصر | نصائح رضوان","en":"What to Do When a Relative Dies Abroad | Radwan Guidance","ru":"Что делать при смерти родственника за рубежом | Советы Радван","fr":"Que faire lors du décès d\'un proche à l\'étranger | Conseils Radwan","es":"Qué hacer ante el fallecimiento de un familiar en el extranjero | Consejos Radwan"}',
'{"ar":"دليل عملي شامل لمساعدة العائلات على اتخاذ الخطوات الصحيحة فور وفاة أحد أقاربهم خارج مصر. نصائح رضوان لتجاوز هذه اللحظات الصعبة.","en":"A comprehensive practical guide to help families take the right steps after a relative dies abroad. Radwan\'s advice for navigating these difficult moments.","ru":"Комплексное практическое руководство — правильные шаги после смерти родственника за рубежом. Советы Радван.","fr":"Guide pratique complet pour prendre les bonnes mesures après le décès d\'un proche à l\'étranger. Les conseils de Radwan.","es":"Guía práctica completa para tomar las medidas correctas tras el fallecimiento de un familiar en el extranjero. Los consejos de Radwan."}',
'{"ar":"وفاة خارج البلاد, وفاة في الخارج, نقل جثمان من الخارج, رضوان, خطوات وفاة المغترب","en":"death abroad, relative dies overseas, repatriation steps, what to do death abroad, Radwan funeral","ru":"смерть за рубежом, родственник умер за границей, шаги репатриации, Радван","fr":"décès à l\'étranger, que faire décès expatrié, rapatriement étapes, Radwan","es":"fallecimiento en el extranjero, familiar muere en el exterior, pasos repatriación, Radwan"}',
'GDN-004',5,
'{"ar":"ماذا تفعل عند وفاة أحد أفراد العائلة في الخارج","en":"What to Do When a Family Member Dies Abroad","ru":"Что делать при смерти члена семьи за рубежом","fr":"Que faire lors du décès d\'un proche à l\'étranger","es":"Qué hacer cuando fallece un familiar en el extranjero"}',
NOW(),NOW());

INSERT INTO blog_details (blog_id, title, content, sort_order, created_at, updated_at) VALUES
(4,
'{"ar":"الثلاث خطوات الأولى في أول ساعة","en":"The Three First Steps in the First Hour","ru":"Три первых шага в первый час","fr":"Les trois premières étapes dans la première heure","es":"Los tres primeros pasos en la primera hora"}',
'{"ar":"تلقي خبر وفاة أحد الأقارب في الخارج صدمة كبيرة. في أول ساعة ركز على: أولاً: اتصل فوراً بشركة رضوان على +201500017444 أو +201116779707 — فريقنا يعمل 24 ساعة طوال الأسبوع وسيتولى كل شيء من اللحظة الأولى. ثانياً: تواصل مع المستشفى أو المكان الذي توفي فيه الشخص للحصول على رقم التواصل الرسمي. ثالثاً: ابحث عن جواز سفر المتوفى أو أي وثيقة هوية رسمية — ستحتاجها في إجراءات النقل.","en":"Receiving news of a relative\'s death abroad is a great shock. In the first hour, focus on: First: Call Radwan immediately at +201500017444 or +201116779707 — our team works 24/7 and will handle everything from the first moment. Second: Contact the hospital or place of death for official contact details. Third: Locate the deceased\'s passport or any official ID — you will need it for transport procedures.","ru":"В первый час: Первое — немедленно позвоните в Радван по +201500017444 — круглосуточная работа. Второе — свяжитесь с больницей. Третье — найдите паспорт усопшего.","fr":"Dans la première heure : Premièrement, appelez Radwan au +201500017444 — disponible 24h/24. Deuxièmement, contactez l\'hôpital. Troisièmement, trouvez le passeport du défunt.","es":"En la primera hora: Primero, llame a Radwan al +201500017444 — disponible 24/7. Segundo, contacte al hospital. Tercero, localice el pasaporte del fallecido."}',
1,NOW(),NOW()),
(4,
'{"ar":"تحذيرات مهمة: لا تدفع لأي طرف قبل التحقق","en":"Important Warnings: Do Not Pay Anyone Before Verifying","ru":"Важные предупреждения: не платите никому без проверки","fr":"Avertissements importants : ne payez personne avant vérification","es":"Advertencias importantes: no pague a nadie sin verificar"}',
'{"ar":"في لحظات الحزن والضغط، يستغل بعض المحتالين الظروف. تحذيرات مهمة: تجنب الوسطاء غير المعروفين الذين يتصلون بك أولاً. لا تدفع أي مبالغ دون عقد رسمي موقع. تحقق دائماً من هوية الشركة وترخيصها الرسمي. شركة رضوان معتمدة رسمياً ومرخصة من الجهات المصرية المختصة. نقدم شفافية كاملة في التكاليف بدون أي رسوم مخفية. يمكنك التواصل معنا أيضاً على +201009924201.","en":"In moments of grief and pressure, fraudsters may exploit the situation. Important warnings: Avoid unknown intermediaries who contact you first. Do not pay any money without a signed official contract. Always verify the company\'s identity and official license. Radwan is officially certified and licensed by competent Egyptian authorities. We provide full transparency with no hidden fees. You can also contact us at +201009924201.","ru":"В моменты горя мошенники могут воспользоваться ситуацией. Избегайте неизвестных посредников. Не платите без договора. Проверяйте лицензию. Радван официально сертифицирован. Никаких скрытых платежей. Также: +201009924201.","fr":"Dans les moments de deuil, méfiez-vous des fraudeurs. Évitez les intermédiaires inconnus. Ne payez rien sans contrat. Vérifiez la licence. Radwan est certifié officiellement. Pas de frais cachés. Contact : +201009924201.","es":"En momentos de duelo, evite estafadores. No pague sin contrato. Verifique la licencia. Radwan está certificado oficialmente. Sin cargos ocultos. También: +201009924201."}',
2,NOW(),NOW());

-- ============================================================
-- المقال 5: خدمات التحنيط الطبي
-- ============================================================

INSERT INTO blogs (id, name, description, image, meta_title, meta_description, meta_keywords, code, category_id, alt_txt, created_at, updated_at) VALUES (
5,
'{"ar":"خدمات التحنيط الطبي: كل ما تحتاج معرفته","en":"Medical Embalming Services: Everything You Need to Know","ru":"Услуги медицинского бальзамирования: всё, что нужно знать","fr":"Services d\'embaumement médical : tout ce que vous devez savoir","es":"Servicios de embalsamamiento médico: todo lo que necesita saber"}',
'{"ar":"شرح شامل لخدمة التحنيط الطبي، أهميتها للشحن الجوي الدولي، الفرق بينها وبين الغسيل الشرعي، والمعايير الدولية التي تلتزم بها شركة رضوان.","en":"A comprehensive explanation of medical embalming services, their importance for international air shipping, the difference from ritual washing, and the international standards Radwan adheres to.","ru":"Полное объяснение услуги медицинского бальзамирования, её важности для авиаперевозки и международных стандартов Радван.","fr":"Explication complète de l\'embaumement médical, son importance pour le fret aérien et les normes internationales de Radwan.","es":"Explicación completa del embalsamamiento médico, su importancia para el flete aéreo y los estándares internacionales de Radwan."}',
NULL,
'{"ar":"خدمات التحنيط الطبي للشحن الجوي | رضوان","en":"Medical Embalming Services for Air Shipping | Radwan","ru":"Услуги медицинского бальзамирования для авиаперевозки | Радван","fr":"Services d\'embaumement médical pour fret aérien | Radwan","es":"Servicios de embalsamamiento médico para envío aéreo | Radwan"}',
'{"ar":"تعرف على خدمات التحنيط الطبي المعتمدة من شركة رضوان. معايير دولية وأطباء معتمدون وشهادات رسمية للشحن الجوي.","en":"Learn about Radwan\'s certified medical embalming services for international air shipping. International standards, certified doctors, and official certificates.","ru":"Узнайте о сертифицированных услугах бальзамирования Радван. Международные стандарты, врачи и официальные документы.","fr":"Découvrez les services d\'embaumement certifiés de Radwan. Normes internationales, médecins certifiés et certificats officiels.","es":"Conozca los servicios de embalsamamiento certificados de Radwan. Estándares internacionales, médicos certificados y certificados oficiales."}',
'{"ar":"تحنيط طبي, خدمات التحنيط في مصر, تحنيط للشحن الجوي, رضوان للتحنيط","en":"medical embalming Egypt, embalming services air shipping, certified embalming, Radwan","ru":"медицинское бальзамирование Египет, бальзамирование авиаперевозка, Радван","fr":"embaumement médical Égypte, embaumement fret aérien, certifié, Radwan","es":"embalsamamiento médico Egipto, embalsamamiento envío aéreo, certificado, Radwan"}',
'EMB-005',2,
'{"ar":"خدمات التحنيط الطبي المعتمدة","en":"Certified Medical Embalming Services","ru":"Сертифицированные услуги бальзамирования","fr":"Services d\'embaumement médical certifiés","es":"Servicios de embalsamamiento médico certificados"}',
NOW(),NOW());

INSERT INTO blog_details (blog_id, title, content, sort_order, created_at, updated_at) VALUES
(5,
'{"ar":"لماذا التحنيط ضرورة وليس خياراً للشحن الجوي؟","en":"Why is Embalming a Necessity, Not an Option, for Air Shipping?","ru":"Почему бальзамирование — необходимость для авиаперевозки?","fr":"Pourquoi l\'embaumement est-il une nécessité pour le fret aérien ?","es":"¿Por qué el embalsamamiento es una necesidad para el envío aéreo?"}',
'{"ar":"تشترط غالبية شركات الطيران الدولية ودول الاستقبال أن يكون الجثمان قد خضع للتحنيط الطبي الكامل قبل قبول شحنته جواً. السبب هو ضمان عدم حدوث أي تحلل أو انبعاثات ضارة أثناء الرحلة. التحنيط يشمل: حقن مواد حافظة طبية خاصة، معالجة التجاويف، وإغلاق الجثمان داخل صندوق زنك محكم. جميع هذه الإجراءات تنفذها شركة رضوان تحت إشراف أطباء حاصلين على تراخيص رسمية.","en":"The majority of international airlines and receiving countries require that the body has undergone complete medical embalming before accepting it as air cargo. The reason is to ensure no decomposition or harmful emissions during the flight. Embalming involves: injecting special medical preservatives, treating cavities, and sealing in a hermetic zinc casket. All these procedures are carried out by Radwan under officially licensed doctors.","ru":"Большинство авиакомпаний требует полного медицинского бальзамирования. Это предотвращает разложение в полёте. Включает: введение консервантов, обработку полостей, запечатывание в цинковый гроб. Выполняется лицензированными врачами Радван.","fr":"La majorité des compagnies aériennes exige l\'embaumement complet. L\'embaumement comprend : injection de conservateurs, traitement des cavités, mise en bière zinc hermétique. Réalisé par des médecins agréés de Radwan.","es":"La mayoría de aerolíneas exige embalsamamiento médico completo. Incluye: inyección de conservantes, tratamiento de cavidades, sellado en ataúd de zinc. Realizado por médicos licenciados de Radwan."}',
1,NOW(),NOW()),
(5,
'{"ar":"التحنيط والشريعة الإسلامية: توضيح مهم","en":"Embalming and Islamic Sharia: An Important Clarification","ru":"Бальзамирование и исламский шариат: важное пояснение","fr":"Embaumement et charia islamique : une clarification importante","es":"Embalsamamiento y la ley islámica: una aclaración importante"}',
'{"ar":"كثير من العائلات المسلمة تتساءل عن حكم التحنيط في الإسلام. الموقف الفقهي الراجح أن التحنيط جائز عند الضرورة، وخاصة عند نقل الجثمان لمسافات طويلة. شركة رضوان تُميّز بوضوح بين: التحنيط الطبي اللازم للشحن (ضرورة عملية مباحة)، والغسل الشرعي الذي يُنفَّذ بشكل منفصل بواسطة أشخاص متخصصين من نفس جنس المتوفى وفق أحكام الشريعة. نحرص على إتمام كلا الإجراءين كاملاً وبالترتيب الصحيح.","en":"Many Muslim families wonder about the Islamic ruling on embalming. The prevailing jurisprudential position is that embalming is permissible out of necessity, especially when transporting a body over long distances. Radwan clearly distinguishes between: medical embalming required for shipping (a permissible practical necessity), and ritual washing performed separately by specialists of the same gender per Islamic law. We ensure both procedures are fully completed in the correct order.","ru":"Многие мусульманские семьи спрашивают об исламском решении по бальзамированию. Преобладающая позиция: допустимо по необходимости при дальних перевозках. Радван чётко разграничивает медицинское бальзамирование и ритуальное омовение по шариату. Оба проводятся в правильном порядке.","fr":"Beaucoup de familles musulmanes s\'interrogent sur l\'embaumement en islam. Position dominante : permis par nécessité. Radwan distingue l\'embaumement médical (permis) de la toilette rituelle selon la charia. Les deux sont effectués dans le bon ordre.","es":"Muchas familias musulmanas preguntan sobre el embalsamamiento en el islam. Posición predominante: permitido por necesidad. Radwan distingue el embalsamamiento médico (permitido) del lavado ritual islámico. Ambos se realizan en el orden correcto."}',
2,NOW(),NOW());

-- ============================================================
-- المقال 6: تكاليف نقل الجثمان دولياً
-- ============================================================

INSERT INTO blogs (id, name, description, image, meta_title, meta_description, meta_keywords, code, category_id, alt_txt, created_at, updated_at) VALUES (
6,
'{"ar":"ما الذي يحدد تكلفة نقل الجثمان دولياً؟","en":"What Determines the Cost of International Deceased Repatriation?","ru":"Что определяет стоимость международной репатриации?","fr":"Qu\'est-ce qui détermine le coût du rapatriement international ?","es":"¿Qué determina el costo de la repatriación internacional?"}',
'{"ar":"شرح شفاف وتفصيلي للعوامل التي تحدد تكلفة نقل الجثمان دولياً، وكيف تضمن شركة رضوان أفضل خدمة بأسعار واضحة وبدون رسوم مخفية.","en":"A transparent and detailed explanation of the factors determining the cost of international deceased repatriation, and how Radwan ensures the best service at clear prices with no hidden fees.","ru":"Прозрачное объяснение факторов стоимости международной репатриации и как Радван обеспечивает лучший сервис без скрытых платежей.","fr":"Explication transparente des facteurs du coût du rapatriement et comment Radwan garantit le meilleur service sans frais cachés.","es":"Explicación transparente de los factores del costo de repatriación y cómo Radwan garantiza el mejor servicio sin cargos ocultos."}',
NULL,
'{"ar":"تكلفة نقل الجثمان دولياً | أسعار شفافة - رضوان","en":"International Repatriation Cost | Transparent Pricing - Radwan","ru":"Стоимость международной репатриации | Прозрачные цены - Радван","fr":"Coût du rapatriement international | Tarifs transparents - Radwan","es":"Costo de repatriación internacional | Precios transparentes - Radwan"}',
'{"ar":"تعرف على العوامل المحددة لتكلفة نقل الجثمان دولياً مع شركة رضوان. أسعار شفافة بدون رسوم مخفية وخدمة متكاملة على مدار الساعة.","en":"Learn about the factors determining the cost of international repatriation with Radwan. Transparent prices with no hidden fees and comprehensive 24/7 service.","ru":"Факторы стоимости репатриации с Радван. Прозрачные цены без скрытых платежей и круглосуточный сервис.","fr":"Facteurs de coût du rapatriement avec Radwan. Prix transparents sans frais cachés et service 24h/24.","es":"Factores del costo de repatriación con Radwan. Precios transparentes sin cargos ocultos y servicio 24/7."}',
'{"ar":"تكلفة نقل الجثمان, سعر شحن الجثامين, تكاليف إعادة الجثمان, رضوان أسعار","en":"repatriation cost, body shipping price, deceased transport cost, Radwan pricing","ru":"стоимость репатриации, цена перевозки усопшего, тарифы Радван","fr":"coût rapatriement, prix transport défunt, tarifs Radwan","es":"costo repatriación, precio traslado fallecido, tarifas Radwan"}',
'CST-006',5,
'{"ar":"تكلفة نقل الجثمان دولياً","en":"International Deceased Repatriation Cost","ru":"Стоимость международной репатриации","fr":"Coût du rapatriement international","es":"Costo de la repatriación internacional"}',
NOW(),NOW());

INSERT INTO blog_details (blog_id, title, content, sort_order, created_at, updated_at) VALUES
(6,
'{"ar":"العوامل الرئيسية المؤثرة في التكلفة","en":"Main Factors Affecting the Cost","ru":"Основные факторы, влияющие на стоимость","fr":"Principaux facteurs influençant le coût","es":"Factores principales que afectan el costo"}',
'{"ar":"تتحدد تكلفة نقل الجثمان دولياً بناءً على عدة عوامل: أولاً — دولة المغادرة والوصول: تختلف الأسعار بحسب المسافة. ثانياً — وزن الجثمان والتابوت: تحتسب الطيران الشحن بالوزن الفعلي أو الحجمي. ثالثاً — نوع التابوت: الفاخر يختلف عن البسيط. رابعاً — متطلبات التحنيط: بعض الحالات تحتاج تحنيطاً موسعاً. خامساً — الرسوم القنصلية: تتفاوت بحسب دولة الوصول وسفارتها في مصر.","en":"The cost of international repatriation is determined by: First — departure and destination country: prices vary by distance. Second — weight of body and casket. Third — type of casket chosen. Fourth — embalming requirements. Fifth — consular and government fees, which vary by destination country and its embassy in Egypt.","ru":"Стоимость определяется: Первое — странами отправления и назначения. Второе — весом тела и гроба. Третье — типом гроба. Четвёртое — требованиями к бальзамированию. Пятое — консульскими сборами.","fr":"Le coût dépend de : Premièrement — pays de départ et de destination. Deuxièmement — poids du corps et cercueil. Troisièmement — type de cercueil. Quatrièmement — exigences d\'embaumement. Cinquièmement — frais consulaires.","es":"El costo depende de: Primero — países de origen y destino. Segundo — peso del cuerpo y ataúd. Tercero — tipo de ataúd. Cuarto — requisitos de embalsamamiento. Quinto — tasas consulares."}',
1,NOW(),NOW()),
(6,
'{"ar":"الشفافية الكاملة: ما تشمله خدمة رضوان","en":"Full Transparency: What Radwan\'s Service Includes","ru":"Полная прозрачность: что включает услуга Радван","fr":"Transparence totale : ce qu\'inclut le service Radwan","es":"Transparencia total: qué incluye el servicio de Radwan"}',
'{"ar":"تلتزم شركة رضوان بمبدأ الشفافية الكاملة في التسعير. العرض يشمل بوضوح: رسوم التحنيط، ثمن التابوت، رسوم مكتب الصحة، رسوم مشرحة زينهم إن وجدت، رسوم السفارة، تكاليف الشحن الجوي، ورسوم التوثيق. لا توجد أي رسوم مفاجئة أو مخفية. نقدم عرضاً مبدئياً مجانياً فور الاتصال بنا على: +201500017444 أو +201116779707 أو +201009924201 أو عبر البريد الإلكتروني: info@radwanfs.com","en":"Radwan is committed to full pricing transparency. The quote clearly includes: medical embalming fees, casket price, health office fees, Zeinhom Morgue fees if applicable, embassy fees, air freight, and documentation fees. No surprise or hidden fees. Free initial quote immediately upon contacting us at: +201500017444 or +201116779707 or +201009924201 or email: info@radwanfs.com","ru":"Радван придерживается полной прозрачности. Предложение включает: бальзамирование, стоимость гроба, санитарные сборы, морг Зейнхом при необходимости, посольские сборы, авиафрахт и документирование. Никаких скрытых платежей. Бесплатная смета: +201500017444, info@radwanfs.com","fr":"Radwan s\'engage à la transparence totale. Le devis inclut : embaumement, cercueil, frais de santé, morgue Zeinhom, ambassade, fret aérien, documentation. Sans frais cachés. Devis gratuit : +201500017444, info@radwanfs.com","es":"Radwan garantiza total transparencia. El presupuesto incluye: embalsamamiento, ataúd, tasas sanitarias, morgue Zeinhom, embajada, flete aéreo, documentación. Sin cargos ocultos. Presupuesto gratuito: +201500017444, info@radwanfs.com"}',
2,NOW(),NOW());

-- ============================================================
-- ④ تحقق من النتيجة النهائية
-- ============================================================
SELECT
  b.id,
  JSON_UNQUOTE(JSON_EXTRACT(b.name, '$.ar')) AS عنوان_المقال,
  JSON_UNQUOTE(JSON_EXTRACT(b.name, '$.en')) AS article_title_en,
  b.code,
  b.category_id,
  COUNT(bd.id) AS عدد_الأقسام
FROM blogs b
LEFT JOIN blog_details bd ON bd.blog_id = b.id
GROUP BY b.id
ORDER BY b.id;
